import{_ as p,o as t,c as e,a5 as r}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"Mapper XML 位置","description":"","frontmatter":{"title":"Mapper XML 位置","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/Mapper XML 位置.md","filePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/Mapper XML 位置.md"}'),i={name:"posts/java快速入门/第五部分：数据库/02-MyBatis/Mapper XML 位置.md"};function o(s,a,l,c,n,m){return t(),e("div",null,[...a[0]||(a[0]=[r('<div><p>对于 MyBatis 的 Mapper XML 文件，我们通常会放在 resources/mapper 目录下，并且命名规则通常会与其对应的 Mapper Java 接口相同，只是文件后缀是 .xml。是不是有地方可以配置这个眼泪</p><p>ChatGPT 在 MyBatis 中，你可以在 MyBatis 配置文件中指定 Mapper XML 文件的位置。这个配置文件通常名为 mybatis-config.xml，位于 src/main/resources 目录下。在这个文件中，你可以使用 &lt;mappers&gt; 标签来指定 Mapper XML 文件的位置。</p><p>例如，如果你将 Mapper XML 文件放在 src/main/resources/mapper 目录下，那么你可以这样配置：</p><p>xml Copy code &lt;configuration&gt; &lt;!-- 其他配置 --&gt; &lt;mappers&gt; &lt;package name=&quot;mapper&quot;/&gt; &lt;/mappers&gt; &lt;/configuration&gt; 如果你使用 Spring Boot 集成 MyBatis，那么你可以在 application.properties 或 application.yml 文件中配置 Mapper XML 文件的位置。例如：</p><p>properties Copy code</p><h1 id="application-properties" tabindex="-1">application.properties <a class="header-anchor" href="#application-properties" aria-label="Permalink to &quot;application.properties&quot;">​</a></h1><p>mybatis.mapper-locations=classpath:mapper/*.xml yaml Copy code</p><h1 id="application-yml" tabindex="-1">application.yml <a class="header-anchor" href="#application-yml" aria-label="Permalink to &quot;application.yml&quot;">​</a></h1><p>mybatis: mapper-locations: classpath:mapper/*.xml 请注意，你需要根据实际的 Mapper XML 文件路径来修改上述配置。</p></div>',1)])])}const _=p(i,[["render",o]]);export{d as __pageData,_ as default};
